function suiteRuntimeMs(units, integrations, e2es) {
  return units * 50 + integrations * 1500 + e2es * 12000;
}

function splitRest(rest) {
  const integration = Math.round(rest * 0.2);
  return { unit: rest - integration, integration };
}

function perTestMs(level) {
  const costs = { unit: 50, integration: 1500, e2e: 12000 };
  if (!(level in costs)) throw new Error("unknown level: " + level);
  return costs[level];
}

function countByLevel(tests) {
  const counts = { unit: 0, integration: 0, e2e: 0 };
  for (const t of tests) counts[t.level] += 1;
  return counts;
}

function isUpsideDown(unit, integration, e2e) {
  return e2e > unit;
}

function slowestLevel(units, integrations, e2es) {
  const totals = { unit: units * 50, integration: integrations * 1500, e2e: e2es * 12000 };
  let best = "unit";
  for (const level of ["integration", "e2e"]) {
    if (totals[level] > totals[best]) best = level;
  }
  return best;
}

function chanceOfFlake(p, n) {
  return 1 - Math.pow(1 - p, n);
}

function projectedRuntimeMs(total, e2ePercent) {
  const e2e = Math.round((total * e2ePercent) / 100);
  const rest = total - e2e;
  const integration = Math.round(rest * 0.2);
  const unit = rest - integration;
  return unit * 50 + integration * 1500 + e2e * 12000;
}

function maxE2ETests(p, limit) {
  let n = 0;
  while (1 - Math.pow(1 - p, n + 1) <= limit) n += 1;
  return n;
}
